package net.civeira.phylax.feature.notification.smtpoutboundconfig.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.notification.smtpoutboundconfig.domain.SmtpOutboundConfig;
import net.civeira.phylax.feature.notification.smtpoutboundconfig.domain.valueobject.RetryDelayVO;

class RetryDelayValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of retry delay of smtp outbound config")
  void test_retry_delay_value_holder_assign_plain_value() {
    Object holder = new Object();
    RetryDelayValueHolder<Object> value = new RetryDelayValueHolder<>(holder);
    Assertions.assertSame(holder, value.retryDelay(1), "Setters must return the holder");
    Assertions.assertTrue(value.getRetryDelayValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals(1, value.getRetryDelay().orElse(null),
        "The plain value must be recovered");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of retry delay of smtp outbound config")
  void test_retry_delay_value_holder_assign_value_object() {
    Object holder = new Object();
    RetryDelayValueHolder<Object> value = new RetryDelayValueHolder<>(holder);
    RetryDelayVO vo = RetryDelayVO.from(1);
    Assertions.assertFalse(value.getRetryDelayValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.retryDelay(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getRetryDelayValue().orElseThrow());
    Assertions.assertSame(holder, value.retryDelay(Optional.empty()));
    Assertions.assertFalse(value.getRetryDelayValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.retryDelay(Optional.of(vo)));
    Assertions.assertSame(vo, value.getRetryDelayValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of retry delay of smtp outbound config against the original")
  void test_retry_delay_value_holder_read() {
    Object holder = new Object();
    RetryDelayValueHolder<Object> value = new RetryDelayValueHolder<>(holder);
    RetryDelayVO vo = RetryDelayVO.from(1);
    RetryDelayVO other = RetryDelayVO.from(1);
    SmtpOutboundConfig original = Mockito.mock(SmtpOutboundConfig.class);
    Mockito.when(original.getRetryDelayValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readRetryDelay(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNull(value.readRetryDelay(Optional.empty(), fails),
        "Without value and original there is no result");
    Assertions.assertFalse(fails.isEmpty(), "A required value must be reported as missing");
    value.retryDelay(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readRetryDelay(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readRetryDelay(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of retry delay of smtp outbound config")
  void test_retry_delay_value_holder_unset() {
    Object holder = new Object();
    RetryDelayValueHolder<Object> value = new RetryDelayValueHolder<>(holder);
    RetryDelayVO vo = RetryDelayVO.from(1);
    value.retryDelay(vo);
    Assertions.assertSame(holder, value.unsetRetryDelayIfMatches("retryDelay_other"));
    Assertions.assertTrue(value.getRetryDelayValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetRetryDelayIfMatches("retryDelay"));
    Assertions.assertFalse(value.getRetryDelayValue().isPresent(),
        "The field name must clear the value");
    value.retryDelay(vo);
    Assertions.assertSame(holder, value.unsetRetryDelay());
    Assertions.assertFalse(value.getRetryDelayValue().isPresent(), "Unset must clear the value");
  }
}
